async ensureBuiltInThemes() {
  const installPromises = [];

  for (const [id, themeInfo] of this.builtInThemeMap.entries()) {
    installPromises.push(
      lazy.AddonManager.maybeInstallBuiltinAddon(
        id,
        themeInfo.version,
        themeInfo.path
      )
    );
  }

  await Promise.all(installPromises);
}

export const BuiltInThemeConfig = new Map([
  [
    "thunderbird-compact-light@mozilla.org",
    {
      version: "1.3.2",
      path: "resource://builtin-themes/light/",
      inApp: true,
      nonNative: true,
    },
  ],
  [
    "thunderbird-compact-dark@mozilla.org",
    {
      version: "1.3.2",
      path: "resource://builtin-themes/dark/",
      inApp: true,
      nonNative: true,
    },
  ],
]);

    null,
    "chrome://messenger/content/troubleshootMode.xhtml",
    "_blank",
    "chrome,centerscreen,modal,resizable=no",
    null
  );
}

// This returns a Promise, but we cannot await it here.
lazy.BuiltInThemes.ensureBuiltInThemes();

if (AppConstants.MOZ_UPDATER) {
  listeners.init();
}

var { BuiltInThemes } = ChromeUtils.importESModule(
  "resource:///modules/BuiltInThemes.sys.mjs"
);

add_task(async function test_builtInThemes() {
  const builtInThemes = BuiltInThemes.getBuiltInThemesDataMap();
  for (const [id, data] of builtInThemes) {
    const theme = await AddonManager.getAddonByID(id);
    Assert.ok(!!theme, `The built-in theme <${id}> should be installed.`);
    Assert.equal(
      data.version,
      theme.version,
      `The built-in theme <${id}> should have the expected version string (forgot to update BuiltInThemeConfig.sys.mjs?)`
    );
  }
});
